const lockUser = `-- name: LockUser :one
SELECT id FROM users WHERE id = $1 FOR UPDATE
`

// Row locks that serialize a count-then-insert limit check and the unshare cleanup (READ COMMITTED has no other guard).
func (q *Queries) LockUser(ctx context.Context, userID int64) (int64, error) {
	row := q.db.QueryRow(ctx, lockUser, userID)
	var id int64
	err := row.Scan(&id)
	return id, err
}

const lockUserNtfy = `-- name: LockUserNtfy :exec
SELECT pg_advisory_xact_lock($1::bigint)
`

// Per-user transaction-scoped advisory lock taken first in the ntfy provisioning transaction, so two concurrent first
// calls provision once (the second waits, then sees the stored id).
func (q *Queries) LockUserNtfy(ctx context.Context, userID int64) error {
	_, err := q.db.Exec(ctx, lockUserNtfy, userID)
	return err
}

