const upsertUser = `-- name: UpsertUser :one


INSERT INTO users (email)
VALUES ($1)
ON CONFLICT (email) DO UPDATE SET email = EXCLUDED.email
RETURNING id, email, auto_remind, default_offsets, ntfy_user_id, start_tab, list_view, calendar_zoom, color_scheme, created_at
`

// Access rule, used by every viewer-scoped query: a viewer sees birthday B iff B.owner_id = viewer id, or a
// birthday_shares row (B.id, viewer email) exists. No query takes a birthday id without the viewer. The viewer email is
// already trimmed and lowercased (ensureUser / EmailOf), so no query lowercases it.
// ---------------------------------------------------------------- users and settings
// The no-op DO UPDATE makes RETURNING work for an existing row.
func (q *Queries) UpsertUser(ctx context.Context, email string) (User, error) {
	row := q.db.QueryRow(ctx, upsertUser, email)
	var i User
	err := row.Scan(
		&i.ID,
		&i.Email,
		&i.AutoRemind,
		&i.DefaultOffsets,
		&i.NtfyUserID,
		&i.StartTab,
		&i.ListView,
		&i.CalendarZoom,
		&i.ColorScheme,
		&i.CreatedAt,
	)
	return i, err
}

const upsertViewerReminder = `-- name: UpsertViewerReminder :execrows

INSERT INTO reminder_settings (birthday_id, user_id, offsets)
SELECT b.id, $1::bigint, $2::smallint[]
FROM birthdays b
WHERE b.id = $3
  AND (b.owner_id = $1
       OR EXISTS (SELECT 1 FROM birthday_shares s WHERE s.birthday_id = b.id AND s.email = $4))
ON CONFLICT (birthday_id, user_id) DO UPDATE SET offsets = EXCLUDED.offsets
`

type UpsertViewerReminderParams struct {
	ViewerID    int64
	Offsets     []int16
	BirthdayID  int64
	ViewerEmail string
}

// ---------------------------------------------------------------- reminder settings (viewer-scoped)
func (q *Queries) UpsertViewerReminder(ctx context.Context, arg UpsertViewerReminderParams) (int64, error) {
	result, err := q.db.Exec(ctx, upsertViewerReminder,
		arg.ViewerID,
		arg.Offsets,
		arg.BirthdayID,
		arg.ViewerEmail,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
